 "deeper": [
  {
   "title": "Why the cycle is the key to every parasitosis",
   "html": "<p>Each step of a cycle is a place where the parasite can be found or stopped. Where it exits tells you which sample to test (stool, urine, sputum); where it enters tells you how to prevent it (wash vegetables, avoid fresh water, use nets); and which hosts it needs tells you where to break transmission (treat dogs for hydatid disease, control snails for bilharzia).</p><p class='src'>Source: the lecture's importance of the life cycle slide.</p>"
  },
  {
   "title": "Why pinworm treatment is repeated",
   "html": "<p>Albendazole kills adult worms but not all eggs, and a child re-infects themselves by scratching and swallowing eggs. The second dose 2-3 weeks later kills the worms that hatched in the meantime, and treating the household and washing bedding stops the loop.</p><p class='src'>Source: the lecture's oxyurosis example.</p>"
  }
 ],
