 "deeper": [
  {
   "title": "Why one negative stool exam proves little",
   "html": "<p>Parasites shed eggs and cysts intermittently and unevenly through the stool, and a microscopist examines only a tiny sample. A single negative result can simply mean an unlucky day. Three samples on different days, each with two concentration methods, raise sensitivity enough to be useful.</p><p class='src'>Source: the lecture's introduction and key points slides.</p>"
  },
  {
   "title": "Why the thick drop and thin smear are used together",
   "html": "<p>The thick drop lyses red cells and piles up many layers of blood, so it finds scanty parasites; but the lysis distorts them, making species identification hard. The thin smear keeps red cells intact, showing the parasite's shape, stage and effect on the red cell, and allows counting parasitaemia. Together they detect and identify.</p><p class='src'>Source: the lecture's blood research methods slides.</p>"
  }
 ],
