 "deeper": [
  {
   "title": "Why two different amoebicides are needed",
   "html": "<p>Metronidazole is absorbed and reaches high levels in the gut wall and liver, killing invasive trophozoites, but little remains in the colonic lumen where minuta forms and cysts persist. Without a luminal agent like paromomycin, the patient stays a cyst carrier and can relapse or infect others.</p><p class='src'>Source: the lecture's treatment slides.</p>"
  },
  {
   "title": "Why stool is often negative in a liver abscess",
   "html": "<p>By the time an abscess forms, the intestinal episode may be months old and amoebae may no longer be shed in stool. The parasite is now in the liver, beyond the reach of a stool exam. That is why visceral amoebiasis is diagnosed by serology and imaging, not coprology.</p><p class='src'>Source: the lecture's biological diagnosis slide.</p>"
  }
 ],
