 "deeper": [
  {
   "title": "Why Giardia causes fatty diarrhoea without blood",
   "html": "<p>Giardia does not invade the mucosa as E. histolytica does; it clings to the surface of the small bowel, flattening the villi and removing the brush border enzymes. The gut can no longer absorb fats and fat-soluble vitamins, so stools become greasy, pale and foul, but there are no ulcers, so no blood.</p><p class='src'>Source: the lecture's pathophysiology slide.</p>"
  },
  {
   "title": "Why both partners must be treated for Trichomonas",
   "html": "<p>Men are often asymptomatic carriers in the urethra or prostate. Treating only the symptomatic woman leaves the reservoir untouched, and she is reinfected at the next contact. Treating both partners at once breaks this ping-pong transmission.</p><p class='src'>Source: the lecture's prevention and therapeutic slide.</p>"
  }
 ],
