 "deeper": [
  {
   "title": "Why cryptosporidiosis is so dangerous in AIDS",
   "html": "<p>Clearance of Cryptosporidium depends on CD4 T cells and interferon-γ. When CD4 cells fall below about 100, the parasite keeps cycling through the enterocytes, with endless autoinfection, profuse diarrhoea and spread to the bile ducts. No drug reliably eradicates it, so restoring immunity with antiretrovirals is the real cure.</p><p class='src'>Source: the lecture's clinical and treatment slides.</p>"
  },
  {
   "title": "Why chlorinated tap water does not stop Cryptosporidium",
   "html": "<p>Cryptosporidium oocysts have a thick wall that resists chlorine at the doses used for drinking water. Animal faeces washing into rivers and reservoirs can therefore contaminate a treated water supply and cause city-wide outbreaks. Filtration, or boiling at home, is what removes them.</p><p class='src'>Source: the lecture's Cryptosporidium and water cycle slides.</p>"
  }
 ],
