 "deeper": [
  {
   "title": "Why falciparum is the killer",
   "html": "<p>P. falciparum invades red cells of any age, so parasitaemia can rise very high, and it places adhesive proteins on the red cell surface that make infected cells stick to capillary walls. These cells pile up in the brain, kidneys and lungs, blocking flow and causing the organ failure of severe malaria. The other species infect a limited pool of red cells and do not sequester in this way.</p><p class='src'>Source: the lecture's cytoadherence and cerebral malaria slides.</p>"
  },
  {
   "title": "Why vivax needs primaquine",
   "html": "<p>Chloroquine clears the parasites in the blood, but P. vivax and P. ovale leave dormant hypnozoites in the liver that can wake months later and cause a new attack. Primaquine is the drug that kills these liver forms; because it can cause haemolysis, G6PD status must be checked first.</p><p class='src'>Source: the lecture's species and Moroccan treatment protocol slides.</p>"
  }
 ],
