 "deeper": [
  {
   "title": "Why early pregnancy infection is rarer but worse",
   "html": "<p>In early pregnancy the placenta is small and a better barrier, so fewer parasites reach the fetus. When they do, they strike organs that are still forming, causing major brain and eye lesions or abortion. Late in pregnancy the placenta lets parasites through easily, but the fetus is mature and receives maternal antibodies at the same time, so lesions are milder or latent.</p><p class='src'>Source: the lecture's pathophysiology slide.</p>"
  },
  {
   "title": "Why IgM alone cannot date an infection",
   "html": "<p>IgM normally marks a recent infection, but in toxoplasmosis it can persist for months or years at low levels. A woman with IgG and IgM may therefore have been infected long before pregnancy. Avidity testing solves this: antibodies bind more strongly as the response matures, so high avidity means the infection is at least four months old.</p><p class='src'>Source: the lecture's serology and avidity slides.</p>"
  }
 ],
