 "deeper": [
  {
   "title": "Why leishmaniasis targets macrophages",
   "html": "<p>Promastigotes are taken up by macrophages, the very cells meant to kill them, and survive by transforming into amastigotes that resist digestion inside the phagolysosome. They multiply there and spread with these cells to the spleen, liver and bone marrow in visceral disease, which is why marrow puncture finds them and why the spleen enlarges.</p><p class='src'>Source: the lecture's life cycle slides.</p>"
  },
  {
   "title": "Why L. tropica and L. major behave differently",
   "html": "<p>L. tropica circulates between humans in towns, producing a single, dry, slow lesion. L. major lives in rural rodents and infects people who enter their habitat; the lesions are multiple and very inflamed but heal faster. Knowing the reservoir explains the setting, the lesion type and the control measures (rodent control vs treating human cases).</p><p class='src'>Source: the lecture's cutaneous leishmaniasis slides.</p>"
  }
 ],
