 "deeper": [
  {
   "title": "Why pinworm keeps coming back",
   "html": "<p>Pinworm eggs are infective as soon as they are laid, on the skin around the anus. Scratching puts them under the nails and on bedding, and they are swallowed or inhaled again within days. That is why one dose is not enough and why the whole household, hands, nails and bedding must be treated at the same time.</p><p class='src'>Source: the lecture's pinworm cycle and treatment slides.</p>"
  },
  {
   "title": "Why Ascaris causes a cough before a stomach ache",
   "html": "<p>Swallowed Ascaris larvae do not stay in the gut at first: they cross into the blood, pass through the liver and lodge in the lungs, where they grow before being coughed up and swallowed again. This lung passage causes Löffler syndrome with eosinophilia weeks before adult worms settle in the intestine and eggs appear in the stool.</p><p class='src'>Source: the lecture's Ascaris cycle slide.</p>"
  }
 ],
