 "deeper": [
  {
   "title": "Why steroids can make strongyloidiasis fatal",
   "html": "<p>Strongyloides can complete its cycle without leaving the body, and the immune system normally keeps this autoinfection at a low level for decades. Corticosteroids suppress that control, so larvae multiply unchecked, cross the gut wall carrying bacteria and spread to every organ. That is why people from endemic areas with eosinophilia should be tested and treated before long-term steroids.</p><p class='src'>Source: the lecture's malignant anguillulosis slide.</p>"
  },
  {
   "title": "Why hookworm causes anaemia",
   "html": "<p>Each adult hookworm clamps onto the duodenal mucosa with its teeth and sucks blood, moving to new sites and leaving small bleeding points. Hundreds of worms mean a steady daily blood and iron loss, producing microcytic hypochromic anaemia, especially in children and pregnant women with poor iron intake. Treatment must therefore combine a dewormer with iron.</p><p class='src'>Source: the lecture's hookworm definition and treatment slides.</p>"
  }
 ],
