 "cards": [
  {
   "id": "x0",
   "type": "text",
   "front": "Define candidiasis.",
   "back": "Cosmopolitan infections by Candida yeasts arising with local or general immunodeficiency: superficial mucocutaneous or deep/disseminated."
  },
  {
   "id": "x1",
   "type": "text",
   "front": "Candida species?",
   "back": "C. albicans (main, commensal); C. glabrata, tropicalis, krusei, parapsilosis, dubliniensis, auris."
  },
  {
   "id": "x2",
   "type": "text",
   "front": "Contributing factors?",
   "back": "Host: newborns, elderly, pregnancy, moisture, dentures, diabetes, neutropenia, HIV. Iatrogenic: antibiotics, steroids, catheters, parenteral nutrition, surgery, burns."
  },
  {
   "id": "x3",
   "type": "text",
   "front": "Mucosal candidiasis forms?",
   "back": "Oral thrush (CD4 < 300), oesophageal (CD4 < 100; dysphagia), digestive, vulvovaginal (75% of women; curd-like discharge), balanitis."
  },
  {
   "id": "x4",
   "type": "text",
   "front": "Cutaneous and nail forms?",
   "back": "Intertrigo of large/small folds with satellite pustules, napkin candidiasis, perionyxis → onyxis of fingernails."
  },
  {
   "id": "x5",
   "type": "text",
   "front": "Systemic candidiasis?",
   "back": "Candidaemia, endophthalmitis, endocarditis, hepatosplenic, bone, brain, urinary, pneumonia; proven/probable/possible criteria."
  },
  {
   "id": "x6",
   "type": "text",
   "front": "Laboratory identification of C. albicans?",
   "back": "Direct exam (budding yeasts), Sabouraud/chromogenic culture, germ-tube test, latex, chlamydospores on RAT/PCB."
  },
  {
   "id": "x7",
   "type": "text",
   "front": "Treatment by form?",
   "back": "Oral: local amphotericin/nystatin/miconazole, fluconazole if recurrent. Skin: local azoles/terbinafine. Nail: local + systemic. Invasive: echinocandins, fluconazole, amphotericin B, voriconazole."
  },
  {
   "id": "img-comm",
   "type": "image",
   "target": "comm",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Candida albicans. Budding yeast, non-capsulated, forming pseudohyphae; normal commensal that becomes pathogenic when defences fail."
  },
  {
   "id": "img-risk",
   "type": "image",
   "target": "risk",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Contributing factors. Newborns, elderly, pregnancy, moisture, dentures, diabetes, neutropenia, HIV; antibiotics, steroids, catheters, surgery, burns."
  },
  {
   "id": "img-muc",
   "type": "image",
   "target": "muc",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Mucosal candidiasis. Oral thrush, oesophageal candidiasis (HIV with CD4 < 100), vulvovaginal candidiasis (75% of women)."
  },
  {
   "id": "img-skin",
   "type": "image",
   "target": "skin",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Cutaneous and nail. Intertrigo of large and small folds, napkin candidiasis, perionyxis leading to onyxis."
  },
  {
   "id": "img-inv",
   "type": "image",
   "target": "inv",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Systemic candidiasis. Candidaemia, endophthalmitis, endocarditis, hepatosplenic, bone, brain and urinary candidiasis."
  },
  {
   "id": "img-dx",
   "type": "image",
   "target": "dx",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Diagnosis. Direct exam, culture on Sabouraud and chromogenic media, germ-tube test for C. albicans, mannan and β-glucan antigens."
  }
 ],
 "deeper": [
  {
   "title": "Why antibiotics cause thrush",
   "html": "<p>In the mouth, gut and vagina, bacteria compete with Candida for space and nutrients and produce substances that keep it in check. Broad-spectrum antibiotics wipe out these bacteria, and Candida, which is unaffected, multiplies freely and invades the epithelium. Removing the cause, not just adding an antifungal, prevents recurrences.</p><p class='src'>Source: the lecture's buccal candidiasis and risk factor slides.</p>"
  },
  {
   "title": "Why a positive culture is not always infection",
   "html": "<p>Candida albicans lives normally on mucosae and in stool, so finding it proves little by itself. What matters is abundance on direct examination, the site (a sterile site such as blood or CSF is always significant), and the clinical picture. That is why the lecture stresses direct examination and antigen testing alongside culture.</p><p class='src'>Source: the lecture's direct examination slide.</p>"
  }
 ],
