 "deeper": [
  {
   "title": "Why pityriasis versicolor leaves pale spots",
   "html": "<p>Malassezia produces substances (such as azelaic acid) that inhibit melanocytes in the infected skin, so the patches stop tanning. When the fungus is killed, the melanocytes need weeks to months to recover, which is why the white spots persist after a successful treatment and why patients must be warned not to mistake this for failure.</p><p class='src'>Source: the lecture's patient information slide.</p>"
  },
  {
   "title": "Why relapse is the rule",
   "html": "<p>Malassezia is part of normal skin flora and cannot be eradicated. The disease reflects local conditions (sweat, sebum, heat, hormones) that let it overgrow. As long as those conditions return, for example each summer, the rash tends to come back, which is why prophylactic shampoos and patient education matter as much as the first treatment.</p><p class='src'>Source: the lecture's definition and patient information slides.</p>"
  }
 ],
