 "deeper": [
  {
   "title": "Why the capsule matters so much",
   "html": "<p>The polysaccharide capsule protects Cryptococcus from phagocytosis and dampens the immune response, making it the main virulence factor. It is also what we detect: India ink outlines it as a halo, and the capsular antigen shed into CSF and blood is the most sensitive diagnostic test and a marker for follow-up.</p><p class='src'>Source: the lecture's pathogen and diagnosis slides.</p>"
  },
  {
   "title": "Why a lumbar puncture is done even without meningeal signs",
   "html": "<p>Cryptococcal meningitis can be almost silent, especially in AIDS, with only mild headache while the yeast multiplies in the CSF. Finding Cryptococcus in the lung, skin or blood therefore requires a lumbar puncture, because missing CNS involvement would mean undertreating a fatal infection.</p><p class='src'>Source: the lecture's neuromeningeal and 'what to do' slides.</p>"
  }
 ],
