 "deeper": [
  {
   "title": "Why neutropenia is the key risk for invasive aspergillosis",
   "html": "<p>Macrophages kill inhaled conidia, but once conidia germinate into hyphae, neutrophils are the cells that destroy them. With fewer than 500 neutrophils for more than about ten days, hyphae grow unopposed into lung tissue and blood vessels, causing infarcts and haemorrhage, which is what the CT halo sign shows.</p><p class='src'>Source: the lecture's defences and IPA slides.</p>"
  },
  {
   "title": "Why galactomannan changed the diagnosis",
   "html": "<p>Cultures and biopsies are slow or too risky in thrombocytopenic patients. Galactomannan is shed by growing Aspergillus into the blood, so twice-weekly screening can flag invasive infection days before symptoms or CT changes. Starting treatment earlier directly improves survival, as the lecture stresses: early diagnosis, better prognosis.</p><p class='src'>Source: the lecture's galactomannan slides.</p>"
  }
 ],
