 "deeper": [
  {
   "title": "Why steroids help in severe pneumocystosis",
   "html": "<p>When cotrimoxazole kills the organisms, their breakdown triggers a burst of lung inflammation that can worsen hypoxaemia in the first days of treatment. Corticosteroids blunt this reaction, which is why they reduce deaths and the need for ventilation in patients who are already hypoxaemic (PaO₂ below 70 mmHg).</p><p class='src'>Source: the lecture's corticotherapy slide.</p>"
  },
  {
   "title": "Why cotrimoxazole prophylaxis matters so much",
   "html": "<p>Before prophylaxis and antiretroviral therapy, Pneumocystis pneumonia was the commonest AIDS-defining illness. A single daily tablet of cotrimoxazole when CD4 fall below 200 largely prevents it, and also protects against toxoplasmosis, making it one of the most effective interventions in HIV care.</p><p class='src'>Source: the lecture's prophylaxis slide and the toxoplasmosis lecture.</p>"
  }
 ],
